probes.api:
local ex = _G.DPC_API_EXAMPLE
if not ex then return "example mod not loaded" end
return ex.snapshot() .. " | " .. tostring(ex.log[#ex.log])

probes.regs:
local R = _G.DPC_dbg and _G.DPC_dbg.R
if not R then return '-' end
local o = {}
for _, r in ipairs(R.api.regs) do if r.off or r.err then o[#o + 1] = r.mod .. ':' .. r.what .. (r.off and ' OFF' or '') end end
return #R.api.regs .. ' regs ' .. table.concat(o, ', ')
